/**
 * Recursively flattens a nodemailer address value (string, `Address`, or
 * nested arrays of either) into a comma-separated string.
 */
function flattenRecipient(value: unknown): string {
    if (!value) return '';
    if (typeof value === 'string') return value;
    if (Array.isArray(value)) {
        return value.map(flattenRecipient).filter(Boolean).join(',');
    }
    return (value as { address?: string }).address ?? '';
}"}
